/// <summary>
///     The <c>AVASalesQuotationTableFrm_AVASalesQuotationLine_SalesPriceCalcFld_Extension</c> class is the extension for <c>SalesQuotationTable</c>
/// </summary>
[ExtensionOf(formControlStr(SalesQuotationTable, AVASalesQuotationLine_SalesPriceCalc))]
final class AVASalesQuotationTableFrm_AVASalesQuotationLine_SalesPriceCalcFld_Extension
{
}

Method.Source:
/// <summary>
///    AVA <c>validate</c> method.
/// </summary>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public boolean validate()
{
    boolean ret;
    str     locCalcStr;
    str     locCalcOperator;
    real    locCalcReal;
    real    locCalcRealResult;
    int     locDotPos;
    int     locCommaPos;

    FormDataSource     locSalesQuotationLineDS;
    SalesQuotationLine locSalesQuotationLine;

    ret = next validate();

    locSalesQuotationLineDS = element.SalesQuotationLine_DS;
    locSalesQuotationLine   = locSalesQuotationLineDS.cursor();

    if (ret)
    {
        locCalcStr              = this.valueStr();
        if(locCalcStr)
        {
            locCalcStr              = strRem(locCalcStr, ' ');

            if(strLen(locCalcStr) <= 1)
            {
                ret = false;
            }

            if (ret)
            {
                locCalcOperator         = subStr(locCalcStr, 1, 1);

                if(locCalcOperator && (locCalcOperator == '+' || locCalcOperator == '-' || locCalcOperator == '*' || locCalcOperator == '/'))
                {
                    locCalcStr =  subStr(locCalcStr, 2, strLen(locCalcStr) - 1);
                }
                else
                {
                    ret = false;
                }
            }
            if (ret)
            {
                if(locCalcStr)
                {
                    locDotPos   = strFind(locCalcStr, '.', 1, strLen(locCalcStr));
                    locCommaPos = strFind(locCalcStr, ',', 1, strLen(locCalcStr));

                    if(locDotPos && locCommaPos)
                    {
                        if(locDotPos < locCommaPos)
                        {
                            locCalcStr  = strReplace(locCalcStr, '.', '');
                            locCalcStr  = strReplace(locCalcStr, ',', '.');
                        }
                        else
                        {
                            locCalcStr  = strReplace(locCalcStr, ',', '');
                        }
                        locCalcReal = str2Num(locCalcStr);
                    }
                    else if(locCommaPos)
                    {
                        locCalcStr  = strReplace(locCalcStr, ',', '.');
                    }
                    locCalcReal = any2Real(locCalcStr);
                }
                else
                {
                    ret = false;
                }
            }
            if (ret)
            {
                if(locCalcReal > 0.0)
                {

                    switch(locCalcOperator)
                    {
                        case '+':
                            locCalcRealResult = locSalesQuotationLine.SalesPrice + locCalcReal;
                            break;
                        case '-':
                            locCalcRealResult = locSalesQuotationLine.SalesPrice - locCalcReal;
                            break;
                        case '*':
                            locCalcRealResult = locSalesQuotationLine.SalesPrice * locCalcReal;
                            break;
                        case '/':
                            locCalcRealResult = locSalesQuotationLine.SalesPrice / locCalcReal;
                            break;
                    }
                }
                else
                {
                    ret = false;
                }
            }
            if (ret)
            {
                if(locCalcRealResult)
                {
                    locSalesQuotationLine.SalesPrice = locCalcRealResult;
                    locSalesQuotationLine.modifiedField(fieldNum(SalesQuotationLine, SalesPrice)); //ToDo: trigger modified
                }
            }
            if (ret)
            {
                this.text('');
            }
            if (!ret)
            {
                this.setFocus();
            }
        }
    }
    return ret;
}
